/**
 * PracticeLoop Lightweight Alpine.js Directives Runtime (Audit A-04 Fix).
 * Evaluates x-data, x-show, x-text, :class, and @click without external CDN dependencies.
 */
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('[x-data]').forEach((el) => {
    const dataExpr = el.getAttribute('x-data');
    let state = {};
    try {
      state = new Function(`return (${dataExpr})`)();
    } catch (e) {
      console.warn('Alpine state init error:', e);
    }

    const updateDOM = () => {
      el.querySelectorAll('[x-show]').forEach((child) => {
        const showExpr = child.getAttribute('x-show');
        try {
          const visible = new Function(...Object.keys(state), `return (${showExpr})`)(...Object.values(state));
          child.style.display = visible ? '' : 'none';
        } catch (e) {}
      });

      el.querySelectorAll('[x-text]').forEach((child) => {
        const textExpr = child.getAttribute('x-text');
        try {
          const val = new Function(...Object.keys(state), `return (${textExpr})`)(...Object.values(state));
          child.textContent = val;
        } catch (e) {}
      });
    };

    el.querySelectorAll('button[@click], [\\@click]').forEach((btn) => {
      const clickExpr = btn.getAttribute('@click');
      btn.addEventListener('click', (ev) => {
        try {
          new Function(...Object.keys(state), `with(this) { ${clickExpr} }`).call(state, ...Object.values(state));
          updateDOM();
        } catch (e) {
          console.warn('@click eval error:', e);
        }
      });
    });

    updateDOM();
  });
});
